// Des: Tests for command line reading
// Flo: words and flags > mode ladder > refuse bad combos
// I/O: argv slices > Args or BadUsage
// Run: zig build test -Dfile=ct-ctrl-args-test.zig
// ===================================================================
const std = @import("std"); const targ = @import("ct-ctrl-args.zig");
test "run post with text and url" { const args = try targ.argsRead(&.{ "run", "post", "--text", "Hello", "--url", "/groups/7/" }); try std.testing.expectEqualStrings("run", args.cmdz); try std.testing.expectEqualStrings("post", args.subz); try std.testing.expectEqualStrings("Hello", args.tsk.text); try std.testing.expectEqualStrings("/groups/7/", args.tsk.url); }
test "mode ladder: default dry, read, live, force" { try std.testing.expectEqual(@import("ru-task-runn.zig").Mode.dry, (try targ.argsRead(&.{"run"})).mode()); try std.testing.expectEqual(@import("ru-task-runn.zig").Mode.read, (try targ.argsRead(&.{ "run", "--read" })).mode()); try std.testing.expectEqual(@import("ru-task-runn.zig").Mode.live, (try targ.argsRead(&.{ "run", "--live" })).mode()); try std.testing.expectEqual(@import("ru-task-runn.zig").Mode.force, (try targ.argsRead(&.{ "run", "--live", "--force" })).mode()); }
test "force without live and read with live are refused" { try std.testing.expectError(error.BadUsage, targ.argsRead(&.{ "run", "--force" })); try std.testing.expectError(error.BadUsage, targ.argsRead(&.{ "run", "--read", "--live" })); }
test "unknown flag, missing value, too many words are refused" { try std.testing.expectError(error.BadUsage, targ.argsRead(&.{ "run", "--nope" })); try std.testing.expectError(error.BadUsage, targ.argsRead(&.{ "run", "post", "--text" })); try std.testing.expectError(error.BadUsage, targ.argsRead(&.{ "a", "b", "c", "d" })); try std.testing.expectError(error.BadUsage, targ.argsRead(&.{ "run", "--max", "x" })); }
test "json, head, conf, max, help flags" { const args = try targ.argsRead(&.{ "status", "--json", "--head", "--conf", "x.json", "--max", "9", "-h" }); try std.testing.expect(args.json and args.head and args.helz); try std.testing.expectEqualStrings("x.json", args.conf); try std.testing.expectEqual(@as(u32, 9), args.tsk.maxn); }
test "all job fields" { const args = try targ.argsRead(&.{ "run", "list", "--title", "T", "--price", "5", "--desc", "D", "--group", "G", "--photo", "p.jpg", "--to", "42" }); try std.testing.expectEqualStrings("T", args.tsk.title); try std.testing.expectEqualStrings("5", args.tsk.price); try std.testing.expectEqualStrings("D", args.tsk.desc); try std.testing.expectEqualStrings("G", args.tsk.group); try std.testing.expectEqualStrings("p.jpg", args.tsk.photo); try std.testing.expectEqualStrings("42", args.tsk.to); }
test "--acct takes a value; all is a value too; missing value is a usage error" { const a1 = try targ.argsRead(&.{ "run", "reply", "--acct", "shop1", "--live" }); try std.testing.expectEqualStrings("shop1", a1.acct); try std.testing.expect(a1.live); const a2 = try targ.argsRead(&.{ "flow", "run", "morning", "--acct", "all" }); try std.testing.expectEqualStrings("all", a2.acct); try std.testing.expectEqualStrings("morning", a2.extr); const a3 = try targ.argsRead(&.{"status"}); try std.testing.expectEqualStrings("", a3.acct); try std.testing.expectError(error.BadUsage, targ.argsRead(&.{ "status", "--acct" })); }
